const SB_URL = 'https://fvjsaourhzzyvvzrgwan.supabase.co';
const SB_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImZ2anNhb3VyaHp6eXZ2enJnd2FuIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc5MjM5NjAwNywiZXhwIjoyMTA3OTcyMDA3fQ.xg86urv7pLbCT7uYklheHpTKt8Dsy3I38MHsElfmD-I';
const sbHeaders = {
