  'Authorization': 'Bearer ' + SB_KEY,
  'Content-Type':  'application/json'
};

// Use values from body if already present (webhook path may send them)
let jdText     = body.jd_text     || body.jdText     || '';
let resumeText = body.resume_summary || body.resumeText || body.resume_text || '';

// ── Fetch JD from campaigns ───────────────────────────────────────────────────
if (!jdText && campaignId) {
  try {
    const camps = await $helpers.httpRequest({
      method:  'GET',
      url:     SB_URL + '/rest/v1/campaigns?select=jd_text&id=eq.' + campaignId,
      headers: sbHeaders,
      json:    true
    });
    jdText = (Array.isArray(camps) && camps[0]?.jd_text) ? camps[0].jd_text : '';
  } catch (e) { jdText = ''; }
}

// ── Fetch resume from decision_ledger ─────────────────────────────────────────
if (!resumeText && candidateId) {
  try {
    const ledger = await $helpers.httpRequest({
      method:  'GET',
      url:     SB_URL + '/rest/v1/decision_ledger?select=raw_text&candidate_id=eq.' + candidateId
             + '&score_type=eq.resume&order=decided_at.desc&limit=1',
